window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[150]={"id":"150","numero":150,"titre":"Otites","objectifs":[{"id":"150-1","rang":"A","rubrique":"Définition","titre":"Connaître les définitions : otalgie, différents types d'otites","contenu":"<p>Vocabulaire séméiologique de base — quatre termes à ne pas confondre :</p>\n      <table >\n        <thead><tr><th style=\"width:22%\">Terme</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-def\">Otalgie</span></th><td>Douleur <span class=\"kw-clinique\">localisée à l'oreille</span> — <strong>pas toujours</strong> liée à une affection de l'oreille (<span class=\"kw-etio\">bouchon de cérumen</span>, <span class=\"kw-etio\">otalgie réflexe</span> d'origine buccopharyngée : pharyngite, angine, <span class=\"kw-clinique\">poussée</span> dentaire)</td></tr>\n          <tr><th><span class=\"kw-def\">Otodynie</span></th><td><span class=\"kw-clinique\">Otalgie</span> <strong>liée à une affection de l'oreille</strong> elle-même (oreille moyenne ou externe)</td></tr>\n          <tr><th><span class=\"kw-def\">Otorrhée</span></th><td><span class=\"kw-clinique\">Écoulement</span> (clair ou purulent) provenant du <span class=\"kw-clinique\">conduit auditif externe</span> — témoin d'une affection de l'oreille, le plus souvent infectieuse (otite externe, otite moyenne perforée)</td></tr>\n          <tr><th><span class=\"kw-def\">Otite</span></th><td><span class=\"kw-def\">Inflammation</span> aiguë ou chronique de l'oreille</td></tr>\n        </tbody>\n      </table>\n\n      <p style=\"margin-top:14px\"><strong><span class=\"kw-clinique\">Les</span> différents types d'otites</strong> se distinguent sur <span class=\"kw-chiffre\">3 critères</span> otoscopiques : inflammation tympanique, épanchement rétrotympanique, otorrhée.</p>\n      <table >\n        <thead><tr><th>Type d'otite</th><th>Inflammation tympanique</th><th>Épanchement rétrotympanique</th><th>Otorrhée</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-def\">Otite congestive</span></th><td><span class=\"kw-imagerie\">Oui</span> (tympan rouge)</td><td>Non</td><td>Non</td></tr>\n          <tr><th><span class=\"kw-def\">OMA purulente</span></th><td><span class=\"kw-imagerie\">Oui</span></td><td><span class=\"kw-imagerie\">Oui</span> (opaque)</td><td>Oui <span class=\"kw-chiffre\">si perforation</span></td></tr>\n          <tr><th><span class=\"kw-def\">Otite séromuqueuse</span></th><td>Non (tympan <span class=\"kw-imagerie\">rétracté</span>)</td><td><span class=\"kw-imagerie\">Oui</span> (liquide clair)</td><td>Non (sauf si <span class=\"kw-ttt\">ATT</span>/drains)</td></tr>\n          <tr><th><span class=\"kw-def\">Otite externe</span></th><td>Non (atteinte du <span class=\"kw-clinique\">CAE</span>)</td><td>Non</td><td><span class=\"kw-clinique\">Oui</span> (abondant)</td></tr>\n        </tbody>\n      </table>\n\n      <p style=\"margin-top:14px\">Au-delà de ces formes aiguës, on distingue <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">otites moyennes chroniques</span> (OMC) — tout processus <span class=\"kw-etio\">inflammatoire</span> de l'oreille moyenne évoluant depuis <span class=\"kw-chiffre\">&gt; 3 mois</span> :</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">OMC bénignes</span></strong> (non cholestéatomateuses, <strong>sans</strong> accumulation de kératine) : otite séromuqueuse, otite chronique à tympan ouvert, séquelles (tympanosclérose, otite atélectasique).</li>\n        <li><strong><span class=\"kw-def\">OMC dangereuses</span></strong> (<span class=\"kw-alerte\">cholestéatomateuses</span>, <strong>avec</strong> accumulation de kératine) : pas de guérison spontanée, risque de <span class=\"kw-alerte\">paralysie faciale</span>, labyrinthite et complications endocrâniennes.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> Toute <span class=\"kw-alerte\">otalgie unilatérale qui ne fait pas sa preuve</span> est a priori symptomatique et doit être surveillée.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 89 — Altération fonction auditive · 103 — <span class=\"kw-clinique\">Vertige</span> · 101 — <span class=\"kw-clinique\">Paralysie faciale</span> · 298 — Tumeur cavité buccale-nasosinusienne-cavum-VADS</em></p>","frequence":0},{"id":"150-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les principaux éléments de l'épidémiologie de l'otite moyenne aiguë (OMA)","contenu":"<p>L'<span class=\"kw-def\">OMA</span> est l'<strong>infection la plus fréquente chez l'enfant</strong> :</p>\n      <ul>\n        <li><span class=\"kw-def\">Incidence</span> <span class=\"kw-clinique\">maximale entre </span><span class=\"kw-chiffre\">6-24 mois</span> (pic à <span class=\"kw-chiffre\">9 mois</span>) ; beaucoup moins fréquente après <span class=\"kw-chiffre\">&gt; 6 ans</span>.</li>\n        <li><span class=\"kw-chiffre\">¾ des enfants</span> ont fait <span class=\"kw-chiffre\">≥ 1 OMA</span> à l'âge de <span class=\"kw-chiffre\">2 ans</span>.</li>\n      </ul>\n\n      <p style=\"margin-top:12px\"><strong><span class=\"kw-def\">Facteurs de risque</span></strong> (endogènes <span class=\"kw-bio\">vs</span> exogènes) :</p>\n      <table >\n        <thead><tr><th style=\"width:30%\">Type</th><th>Facteurs de risque</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-etio\">FR endogènes</span></th><td>\n            <strong>Précocité</strong> du 1ᵉʳ épisode d'OMA ; <strong>hérédité</strong> (ATCD familiaux d'<span class=\"kw-def\">OMA</span>/<span class=\"kw-def\">OSM</span>)<br>\n            <span class=\"kw-etio\">Déficits immunitaires</span> ; <span class=\"kw-etio\">RGO</span> ; <span class=\"kw-etio\">carence martiale</span><br>\n            <span class=\"kw-etio\">Trisomie 21</span> ; <span class=\"kw-etio\">malformations craniofaciales</span> ; <span class=\"kw-etio\">fentes / anomalies vélopalatines</span> (même opérées)<br>\n            <span class=\"kw-etio\">Pathologies ciliaires</span> (syndrome de <span class=\"kw-def\">Kartagener</span> : ralentissement du battement des cils + situs inversus)\n          </td></tr>\n          <tr><th><span class=\"kw-etio\">FR exogènes</span></th><td>\n            <strong><span class=\"kw-etio\">Absence d'allaitement maternel</span></strong> ; vie en <span class=\"kw-etio\">collectivité</span> (crèche)<br>\n            Saison <span class=\"kw-etio\">automno-hivernale</span> ; <span class=\"kw-etio\">tabagisme passif</span> (irrite la muqueuse, paralyse <span class=\"kw-clinique\">les</span> cils)<br>\n            <span class=\"kw-etio\">Pollution atmosphérique</span> ; <span class=\"kw-etio\">précarité</span> des conditions de vie et d'hygiène\n          </td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 149 — Angine - rhinopharyngite</em></p>","frequence":3},{"id":"150-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les éléments de physiopathologie de l'OMA","contenu":"<div class=\"callout callout-info\">\n        <strong>Dogme.</strong> Toute OMA provient d'une <span class=\"kw-etio\">infection via le rhinopharynx</span> par l'intermédiaire de la <span class=\"kw-def\">trompe auditive</span> (trompe d'Eustache).\n      </div>\n\n      <p><strong>Séquence physiopathologique en 3 temps :</strong></p>\n      <table >\n        <thead><tr><th style=\"width:24%\">Étape</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><th>1 · <span class=\"kw-etio\">Rhinopharyngite virale</span></th><td>Inflammation du rhinopharynx → <strong><span class=\"kw-clinique\">trouble de la perméabilité tubaire</span></strong></td></tr>\n          <tr><th>2 · <span class=\"kw-def\">Otite congestive</span></th><td><span class=\"kw-clinique\">Dépression de l'oreille moyenne</span> secondaire au trouble de perméabilité tubaire</td></tr>\n          <tr><th>3 · <span class=\"kw-def\">OMA purulente</span></th><td><span class=\"kw-etio\">Surinfection bactérienne</span> par contiguïté : altération du <span class=\"kw-clinique\">tapis mucociliaire</span>, adhérence/multiplication des bactéries du cavum, <span class=\"kw-etio\">colonisation</span> de l'oreille moyenne par la trompe auditive</td></tr>\n        </tbody>\n      </table>\n\n      <p style=\"margin-top:12px\"><strong>Germes</strong> de l'OMA purulente (souvent monomicrobienne) :</p>\n      <ul>\n        <li><span class=\"kw-bio\"><em>Streptococcus pneumoniae</em></span> (<span class=\"kw-etio\">pneumocoque</span>) ≈ <span class=\"kw-chiffre\">40 %</span> des cas.</li>\n        <li><span class=\"kw-bio\"><em>Haemophilus influenzae</em></span> ≈ <span class=\"kw-chiffre\">30-40 %</span> (entre 6 et <span class=\"kw-chiffre\">36 mois</span>) — évoquer si <span class=\"kw-clinique\">conjonctivite purulente</span> associée.</li>\n        <li><span class=\"kw-bio\"><em>Moraxella (Branhamella) catarrhalis</em></span> : plus rare, rôle discuté.</li>\n      </ul>\n\n      <p style=\"margin-top:12px\"><strong>Pourquoi l'enfant ?</strong> La <span class=\"kw-def\">prévalence</span> particulière s'explique par :</p>\n      <ul>\n        <li>Charge infectieuse rhinopharyngée supérieure (<span class=\"kw-clinique\">rhinopharyngites à répétition</span>).</li>\n        <li><span class=\"kw-def\">Trompe auditive</span> plus <strong>courte, horizontale et perméable jusqu'à <span class=\"kw-chiffre\">6-7 ans</span></strong> → toute anomalie tubaire facilite <span class=\"kw-clinique\">les</span> OMA (fente palatine, trisomie 21).</li>\n        <li>Toute <span class=\"kw-def\">OSM</span> est un facteur facilitant la répétition des OMA.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 149 — Angine - rhinopharyngite</em></p>","frequence":3},{"id":"150-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d'OMA (démarche diagnostique, examen clinique dont otoscopie)","contenu":"<div class=\"callout callout-info\">\n        <strong>Diagnostic clinique + otoscopique.</strong> Seul un examen <span class=\"kw-imagerie\">otoscopique</span> de bonne qualité permet d'affirmer le diagnostic et de différencier <span class=\"kw-clinique\">les</span> types d'otite — débuter par l'oreille présumée saine, et <strong>ne pas oublier d'examiner l'autre oreille</strong> (bilatéralité fréquente), le nez et le pharynx.\n      </div>\n\n      <p><strong>Contexte</strong> : au cours ou au décours d'une <span class=\"kw-etio\">rhinopharyngite</span> ± fébrile.</p>\n      <p><strong>Symptômes</strong> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Fièvre</span>.</li>\n        <li><span class=\"kw-clinique\">Otalgie</span> par paroxysmes (« coliques de l'oreille ») — exprimée verbalement (<span class=\"kw-chiffre\">≥ 3 ans</span>) ou par des équivalents (<span class=\"kw-clinique\">pleurs</span>, <span class=\"kw-clinique\">insomnie</span>, <span class=\"kw-clinique\">irritabilité</span>).</li>\n        <li><span class=\"kw-clinique\">Hypoacousie de transmission</span>.</li>\n        <li><span class=\"kw-clinique\">Otorrhée</span> : parfois 1ᵉʳ signe si tympan perforé (l'<span class=\"kw-clinique\">otalgie</span> est alors peu marquée).</li>\n        <li>Signe associé : <strong><span class=\"kw-def\">syndrome otite-conjonctivite</span></strong> (conjonctivite purulente) → <span class=\"kw-bio\"><em>H. influenzae</em> non typable</span>.</li>\n      </ul>\n\n      <p style=\"margin-top:12px\"><strong>Otoscopie — deux stades à distinguer :</strong></p>\n      <table >\n        <thead><tr><th style=\"width:24%\"><span class=\"kw-def\">Stade</span></th><th>Aspect du tympan</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-def\">Stade congestif</span></th><td>\n            <strong>Positif :</strong> <span class=\"kw-imagerie\">congestion tympanique</span> (rougeur, hypervascularisation)<br>\n            <strong>Négatif :</strong> <span class=\"kw-imagerie\">sans épanchement</span> ; <span class=\"kw-imagerie\">reliefs du marteau conservés</span> ; pas de bombement\n          </td></tr>\n          <tr><th><span class=\"kw-def\">Stade collecté</span></th><td>\n            <strong>Tympan fermé :</strong> tympan <span class=\"kw-imagerie\">rouge violacé</span> ; <span class=\"kw-imagerie\">disparition du triangle lumineux</span> ; <span class=\"kw-imagerie\">bombement</span> avec disparition des reliefs ; <span class=\"kw-imagerie\">opacité rétrotympanique</span><br>\n            <strong>Tympan perforé :</strong> <span class=\"kw-imagerie\">perforation punctiforme</span> + écoulement <span class=\"kw-clinique\">pulsatile mucopurulent</span>\n          </td></tr>\n        </tbody>\n      </table>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/150/otoscopie-stades-oma.png\" alt=\"Aspects otoscopiques comparés : tympan normal, otite congestive, OMA collectée, tympan perforé\" loading=\"lazy\">\n        <figcaption>Aspects otoscopiques : tympan normal, otite congestive, OMA collectée (courte apophyse du marteau, disparition du triangle lumineux), tympan perforé. Source : fiche source EDN item 150.</figcaption>\n      </figure>\n\n      <p style=\"margin-top:12px\"><strong>Diagnostics différentiels de l'<span class=\"kw-clinique\">otalgie</span></strong> :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Otite externe</span> / <span class=\"kw-clinique\">furoncle</span> du conduit : douleur lancinante non paroxystique, exacerbée par la <span class=\"kw-clinique\">mastication</span>, la <span class=\"kw-clinique\">pression du tragus</span>, la mobilisation du pavillon.</li>\n        <li><span class=\"kw-etio\">Zona auriculaire</span> : <span class=\"kw-clinique\">éruption</span> dans la conque (zone de <span class=\"kw-def\">Ramsay-Hunt</span>) + <span class=\"kw-alerte\">paralysie faciale</span>.</li>\n        <li><span class=\"kw-etio\">Otalgie réflexe</span> (pharyngée, dentaire, ATM) : à évoquer si l'otoscopie est <strong>normale</strong>.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 89 — Altération fonction auditive</em></p>","frequence":3},{"id":"150-5","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l'indication des examens d'imagerie devant une otite infectieuse de l'adulte et de l'enfant","contenu":"<div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> Le diagnostic d'OMA est <span class=\"kw-def\">clinique</span>, confirmé par l'otoscopie. <strong>Aucun examen complémentaire n'est nécessaire</strong> dans l'OMA purulente <span class=\"kw-chiffre\">non compliquée</span>.\n      </div>\n\n      <table >\n        <thead><tr><th style=\"width:26%\">Examen</th><th>Indication</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-imagerie\">Imagerie</span> (<span class=\"kw-imagerie\">TDM</span> ± <span class=\"kw-imagerie\">IRM</span>)</th><td>\n            <strong>Uniquement si <span class=\"kw-alerte\">complication</span> d'une OMA purulente.</strong><br>\n            <span class=\"kw-imagerie\">TDM injectée</span> : <span class=\"kw-imagerie\">opacité mastoïdienne</span> (mastoïdite) ; recherche surtout des <span class=\"kw-alerte\">complications méningo-encéphaliques</span> latentes (<span class=\"kw-def\">incidence</span> ≈ <span class=\"kw-chiffre\">10 %</span>).<br>\n            <span class=\"kw-imagerie\">IRM</span> : si suspicion d'<span class=\"kw-alerte\">extension endocrânienne</span>.\n          </td></tr>\n          <tr><th><span class=\"kw-bio\">Explorations auditives</span></th><td>Utiles seulement en cas d'<span class=\"kw-def\">otite séromuqueuse</span> (audiométrie + tympanométrie)</td></tr>\n          <tr><th><span class=\"kw-bio\">Paracentèse</span> (documentation bactériologique)</th><td>\n            OMA suppurée <span class=\"kw-clinique\">hyperalgique</span> avec échec de l'antalgie ; OMA suppurée <span class=\"kw-clinique\">très fébrile</span> résistante aux antipyrétiques<br>\n            Après <span class=\"kw-chiffre\">2 échecs</span> d'une ATB bien conduite ; <span class=\"kw-alerte\">mastoïdite</span>, <span class=\"kw-alerte\">paralysie faciale</span><br>\n            <span class=\"kw-alerte\">AEG</span> ; <span class=\"kw-clinique\">évolution</span> anormale/compliquée ; otites récidivantes ou traînantes ; <span class=\"kw-chiffre\">nourrisson &lt; 3 mois</span> ; <span class=\"kw-etio\">déficit immunitaire</span>\n          </td></tr>\n        </tbody>\n      </table>\n      <p style=\"margin-top:6px;font-size:13px;color:var(--ink-muted)\">Technique : incision du quadrant antéro-inférieur ou postéro-inférieur du tympan (à distance des osselets).</p>","frequence":3},{"id":"150-6","rang":"A","rubrique":"Prise en charge","titre":"Connaître la stratégie initiale de la prise en charge de l'OMA : antibiothérapie, traitements associés","contenu":"<p><strong>Orientation :</strong> prise en charge <span class=\"kw-chiffre\">ambulatoire</span> le plus souvent. <span class=\"kw-alerte\">Hospitalisation</span> réservée aux formes <span class=\"kw-alerte\">compliquées</span> ; avis ORL rare (complications locorégionales, OSM compliquée, <span class=\"kw-chiffre\">2ᵉ échec</span> d'ATB).</p>\n\n      <p><strong>Traitement symptomatique (toujours) :</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Désobstruction rhinopharyngée</span> : sérum physiologique + mouchage.</li>\n        <li><span class=\"kw-ttt\">Paracétamol</span> / <span class=\"kw-ttt\">antalgiques</span> ; <span class=\"kw-ttt\">ibuprofène</span> si douleur intense ; instillations auriculaires antalgiques.</li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong>À ne pas faire.</strong> <span class=\"kw-ci\">Corticoïdes</span> non indiqués ; <span class=\"kw-ci\">vasoconstricteurs</span> <span class=\"kw-ci\">contre-indiqués</span> (prudence chez le nourrisson).\n      </div>\n\n      <p style=\"margin-top:12px\"><strong><span class=\"kw-ttt\">Antibiothérapie</span> générale — indications <span class=\"kw-bio\">vs</span> non-indications :</strong></p>\n      <table >\n        <thead><tr><th style=\"width:50%\">ATB indiquée</th><th>ATB NON indiquée</th></tr></thead>\n        <tbody>\n          <tr><td>\n            OMA purulente <strong><span class=\"kw-chiffre\">&lt; 2 ans</span> systématiquement</strong><br>\n            OMA purulente <span class=\"kw-chiffre\">≥ 2 ans</span> avec <span class=\"kw-clinique\">symptomatologie bruyante</span> (<span class=\"kw-clinique\">otalgie</span> intense, <span class=\"kw-clinique\">fièvre</span> élevée, otorrhée par perforation spontanée)<br>\n            Persistance des symptômes après <span class=\"kw-chiffre\">48-72 h</span> de traitement symptomatique<br>\n            OMA compliquant une maladie générale (<span class=\"kw-etio\">rougeole</span>, <span class=\"kw-etio\">varicelle</span>, <span class=\"kw-etio\">scarlatine</span>)<br>\n            Otorrhée sur OMA perforée persistant <span class=\"kw-chiffre\">&gt; 1 semaine</span>\n          </td><td>\n            <span class=\"kw-def\">OMA congestive</span> (<span class=\"kw-def\">stade</span> catarrhal)<br>\n            <span class=\"kw-def\">Otite séromuqueuse</span><br>\n            <span class=\"kw-def\">Otite externe</span> (sauf compliquée)<br>\n            <strong>OMA purulente <span class=\"kw-chiffre\">≥ 2 ans</span> peu symptomatique</strong> → <span class=\"kw-chiffre\">abstention</span> + <span class=\"kw-def\">surveillance</span> + <strong><span class=\"kw-def\">réévaluation</span> à <span class=\"kw-chiffre\">48-72 h</span></strong> (licite)\n          </td></tr>\n        </tbody>\n      </table>\n\n      <p style=\"margin-top:12px\"><strong>Molécules :</strong></p>\n      <table >\n        <thead><tr><th style=\"width:42%\">Situation</th><th>Antibiotique</th></tr></thead>\n        <tbody>\n          <tr><th>1ʳᵉ intention</th><td><strong><span class=\"kw-ttt\">Amoxicilline</span> <span class=\"kw-chiffre\">80-90 mg/kg/j</span> en <span class=\"kw-chiffre\">3 prises</span></strong></td></tr>\n          <tr><th><span class=\"kw-def\">Syndrome otite-conjonctivite</span> (<em>H. influenzae</em>)</th><td><span class=\"kw-ttt\">Amoxicilline + acide clavulanique</span></td></tr>\n          <tr><th><span class=\"kw-ci\">Allergie</span> aux pénicillines (sans CI aux céphalo)</th><td><span class=\"kw-ttt\">Cefpodoxime-proxétil</span> (ou céfuroxime-axétil)</td></tr>\n          <tr><th>CI à toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-ci\">β-lactamines</span></th><td><span class=\"kw-ttt\">Érythromycine-sulfafurazole</span> ou <span class=\"kw-ttt\">cotrimoxazole</span> (adulte : <span class=\"kw-ttt\">cotrimoxazole</span> ou <span class=\"kw-ttt\">lévofloxacine</span>)</td></tr>\n          <tr><th>Voie parentérale (exceptionnelle : <span class=\"kw-chiffre\">&lt; 3 mois</span>, immunodépression, <span class=\"kw-ci\">intolérance</span> digestive)</th><td><span class=\"kw-ttt\">Ceftriaxone IV/IM</span></td></tr>\n        </tbody>\n      </table>\n      <p style=\"margin-top:6px;font-size:13px;color:var(--ink-muted)\">Plus de <span class=\"kw-ttt\">fluoroquinolones</span> chez l'enfant dans cette indication.</p>\n\n      <p style=\"margin-top:12px\"><strong>Durée :</strong></p>\n      <ul>\n        <li><span class=\"kw-chiffre\">&lt; 2 ans</span> → <strong><span class=\"kw-chiffre\">8-10 jours</span></strong>.</li>\n        <li><span class=\"kw-chiffre\">≥ 2 ans</span> → <strong><span class=\"kw-chiffre\">5 jours</span></strong>.</li>\n        <li>Otorrhée ou rechute d'OMA purulente → <strong><span class=\"kw-chiffre\">10 jours</span></strong>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Point pharmaco (discriminant QCM).</strong> La résistance du <span class=\"kw-bio\">pneumocoque</span> = <strong>modification de la cible (<span class=\"kw-def\">PLP</span>)</strong>, pas de <span class=\"kw-bio\">β-lactamase</span> → l'<span class=\"kw-ttt\">acide clavulanique</span> est <strong>inutile</strong> contre lui (on augmente la posologie d'<span class=\"kw-ttt\">amoxicilline</span>). Il n'est utile que contre <span class=\"kw-bio\"><em>H. influenzae</em></span> et <span class=\"kw-bio\"><em>M. catarrhalis</em></span> (β-lactamases). FR de PSDP chez l'enfant : âge <span class=\"kw-chiffre\">&lt; 18 mois</span>, ATCD récent d'OMA, vie en collectivité, ATB aminopénicilline dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">&lt; 3 mois</span>.\n      </div>\n\n      <p style=\"margin-top:12px\"><strong>ATB locale</strong> (solution d'<span class=\"kw-ttt\">ofloxacine</span>, <span class=\"kw-chiffre\">7 j</span>) : réservée aux <span class=\"kw-def\">otites externes</span>, otites chroniques à tympan ouvert, otorrhées sur <span class=\"kw-ttt\">aérateurs transtympaniques</span> — <strong>PAS dans l'OMA purulente perforée</strong>. <span class=\"kw-ci\">Aminosides</span> <span class=\"kw-ci\">contre-indiqués</span> si perforation tympanique (ototoxicité).</p>\n\n      <p><strong>Prévention :</strong> <span class=\"kw-ttt\">vaccination</span> <span class=\"kw-ttt\">antipneumococcique conjuguée</span> (réduit <span class=\"kw-clinique\">les</span> OMA purulentes) ; <span class=\"kw-ttt\">aérateurs transtympaniques</span> si OSM prédisposante. <span class=\"kw-def\">Réévaluation</span> à <span class=\"kw-chiffre\">48-72 h</span> si abstention ou persistance.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 146 — <span class=\"kw-ttt\">Vaccination</span> · 147 — <span class=\"kw-clinique\">Fièvre</span> aiguë</em></p>","frequence":6},{"id":"150-7","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principales complications de l'OMA","contenu":"<p><strong><span class=\"kw-alerte\">Mastoïdite</span> = complication classique</strong> de l'OMA : issue de pus à travers la corticale de l'os mastoïdien dans une OMA collectée (≈ <span class=\"kw-chiffre\">1/10 000</span> OMA).</p>\n      <ul>\n        <li>Tableau d'OMA + <span class=\"kw-clinique\">syndrome général important</span>.</li>\n        <li><span class=\"kw-clinique\">Tuméfaction inflammatoire rétroauriculaire</span> douloureuse : <span class=\"kw-clinique\">décollement du pavillon</span> (en dehors, en avant, en bas) + chute de la paroi postérieure du <span class=\"kw-clinique\">CAE</span>.</li>\n        <li><span class=\"kw-imagerie\">TDM injectée</span> ; traitement <strong>hospitalier</strong> : <span class=\"kw-ttt\">ATB parentérale</span> ± <span class=\"kw-ttt\">drainage</span> chirurgical.</li>\n      </ul>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/150/tdm-mastoidite.png\" alt=\"TDM en coupe axiale d'une mastoïdite droite : comblement des cellules mastoïdiennes et collection sous-périostée\" loading=\"lazy\">\n        <figcaption>Mastoïdite droite (<span class=\"kw-imagerie\">TDM</span>, coupes axiales) : comblement des cellules mastoïdiennes, collection sous-périostée (hypodense, paroi rehaussée), <span class=\"kw-clinique\">empyème</span> temporal. Source : fiche source EDN item 150.</figcaption>\n      </figure>\n\n      <p style=\"margin-top:12px\"><strong>Autres complications :</strong></p>\n      <table >\n        <thead><tr><th style=\"width:30%\">Complication</th><th>Points clés</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-alerte\">Paralysie faciale périphérique</span></th><td>Fréquence ≈ <span class=\"kw-chiffre\">5/1000</span> ; <span class=\"kw-imagerie\">imagerie indiquée</span> ; <span class=\"kw-ttt\">ATB</span> + <span class=\"kw-ttt\">corticoïdes</span> + <span class=\"kw-ttt\">paracentèse</span></td></tr>\n          <tr><th><span class=\"kw-alerte\">Méningite</span></th><td>Fréquence ≈ <span class=\"kw-chiffre\">1/10 000</span> ; germe = <span class=\"kw-bio\">pneumocoque</span> ; voie hématogène/osseuse/labyrinthique ; <span class=\"kw-imagerie\">imagerie indiquée</span></td></tr>\n          <tr><th><span class=\"kw-def\">Perforation tympanique</span></th><td>Fermeture spontanée habituelle ; possible passage à la chronicité</td></tr>\n          <tr><th><span class=\"kw-alerte\">Labyrinthite</span></th><td><span class=\"kw-clinique\">Surdité de perception</span> + <span class=\"kw-clinique\">vertiges</span>, nystagmus</td></tr>\n          <tr><th>Rares</th><td><span class=\"kw-alerte\">Thrombophlébite du sinus latéral</span> ; <span class=\"kw-alerte\">abcès cérébral</span> ; ostéite du temporal ; <span class=\"kw-alerte\">bactériémie</span></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Complication la plus fréquente.</strong> L'<span class=\"kw-def\">otite séromuqueuse</span> complique <span class=\"kw-chiffre\">10-20 %</span> des OMA → justifie de <strong>recontrôler tout patient à <span class=\"kw-chiffre\">4-6 semaines</span></strong> de son épisode d'OMA.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 101 — <span class=\"kw-clinique\">Paralysie faciale</span> · 151 — <span class=\"kw-clinique\">Méningite</span> - méningoencéphalite</em></p>","frequence":1},{"id":"150-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic de l'otite externe et séro-muqueuse","contenu":"<div style=\"border-left:3px solid var(--spe-orl);padding-left:12px;margin-bottom:16px\">\n        <h4 style=\"margin:0 0 8px\"><span class=\"kw-def\">Otite externe</span> <span style=\"font-weight:400;color:var(--ink-muted)\">(dermo-épidermite du conduit auditif externe)</span></h4>\n        <ul>\n          <li><strong>Germes :</strong> bactéries (<span class=\"kw-bio\"><em>S. aureus</em></span>, <span class=\"kw-bio\"><em>Pseudomonas aeruginosa</em></span>) ; champignons ≈ <span class=\"kw-chiffre\">10 %</span> (<span class=\"kw-bio\"><em>Aspergillus</em></span> : aspect filamenteux + <span class=\"kw-imagerie\">taches noires</span> à l'otoscope).</li>\n          <li><strong>FR :</strong> <span class=\"kw-etio\">baignade</span> (« otite du nageur »), <span class=\"kw-etio\">traumatismes du conduit</span>, <span class=\"kw-etio\">macération</span>.</li>\n          <li><strong>Clinique :</strong> <span class=\"kw-clinique\">otalgie intense</span> lancinante, augmentant en <span class=\"kw-clinique\">1ʳᵉ partie de nuit</span>, <strong>majorée par la <span class=\"kw-clinique\">palpation du tragus</span> / <span class=\"kw-clinique\">traction du pavillon</span> / introduction de l'otoscope / <span class=\"kw-clinique\">mastication</span></strong> ; <span class=\"kw-clinique\">otorrhée purulente</span> ; <strong><span class=\"kw-chiffre\">pas de fièvre</span></strong>.</li>\n          <li><strong>Otoscopie :</strong> <span class=\"kw-clinique\">CAE</span> <span class=\"kw-imagerie\">inflammatoire, œdématié, douloureux</span>, recouvert de sécrétions purulentes ; <span class=\"kw-imagerie\">tympan non inflammatoire</span> (difficile à analyser).</li>\n        </ul>\n        <div class=\"callout callout-danger\">\n          <strong><span class=\"kw-alerte\">Drapeau rouge</span> — <span class=\"kw-alerte\">otite maligne externe (nécrosante)</span>.</strong> Extension au rocher puis à la base du crâne (ostéite). <span class=\"kw-def\">Terrain</span> : <span class=\"kw-etio\">diabétique</span>, <span class=\"kw-etio\">immunodéprimé</span>, <span class=\"kw-etio\">grand âge</span> ; germe = <span class=\"kw-bio\"><em>Pseudomonas aeruginosa</em></span>. Tableau : <span class=\"kw-alerte\">AEG</span> + otite externe traînante <strong>résistante au traitement local</strong> + <span class=\"kw-alerte\">paralysie de nerfs crâniens</span> ; <span class=\"kw-imagerie\">polype du CAE</span> évocateur. <span class=\"kw-imagerie\">TDM/IRM</span>. <strong><span class=\"kw-alerte\">Urgence</span></strong> diagnostique et thérapeutique.\n        </div>\n      </div>\n\n      <div style=\"border-left:3px solid var(--warn,#b45309);padding-left:12px\">\n        <h4 style=\"margin:0 0 8px\"><span class=\"kw-def\">Otite séromuqueuse</span> (OSM) <span style=\"font-weight:400;color:var(--ink-muted)\">(otite chronique à tympan fermé &gt;<span class=\"kw-chiffre\"> 3 mois</span>, sans infection aiguë)</span></h4>\n        <ul>\n          <li><strong><span class=\"kw-def\">Épidémiologie</span> :</strong> <strong>cause la plus fréquente de <span class=\"kw-clinique\">surdité de transmission</span> entre <span class=\"kw-chiffre\">1 et 6 ans</span></strong> ; âge moyen <span class=\"kw-chiffre\">5 ans</span> ; touche ≈ <span class=\"kw-chiffre\">50 %</span> des enfants ; <span class=\"kw-clinique\">bilatérale dans </span><span class=\"kw-chiffre\">85 %</span> des cas.</li>\n          <li><strong>Clinique :</strong> <span class=\"kw-clinique\">hypoacousie</span> (mode de révélation), otalgies fugaces, sensation d'oreille pleine, <span class=\"kw-clinique\">autophonie</span> ; <strong><span class=\"kw-chiffre\">pas de fièvre</span></strong>.</li>\n          <li><strong>Otoscopie :</strong> tympan <span class=\"kw-imagerie\">rétracté</span>, <span class=\"kw-imagerie\">ambré / mat / jaunâtre</span>, fines stries vasculaires, <span class=\"kw-imagerie\">immobile</span> au spéculum pneumatique de Siegle / Valsalva, <strong>non <span class=\"kw-etio\">inflammatoire</span></strong> ; épanchement rétrotympanique (bulles, niveau liquidien).</li>\n          <li><strong>Paraclinique :</strong> <span class=\"kw-bio\">audiométrie</span> = <span class=\"kw-clinique\">surdité de transmission</span> (moyenne ≈ <span class=\"kw-chiffre\">27 dB</span>) ; <span class=\"kw-bio\">tympanogramme</span> = <strong><span class=\"kw-imagerie\">courbe plate type B</span></strong> (absence de mobilité tympanique).</li>\n        </ul>\n        <div class=\"callout callout-warn\">\n          <strong>Piège majeur.</strong> Une <span class=\"kw-alerte\">OSM unilatérale</span> impose de rechercher une <span class=\"kw-alerte\">tumeur maligne du cavum</span> par <span class=\"kw-imagerie\">nasofibroscopie</span> — y compris chez l'enfant.\n        </div>\n      </div>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/150/otoscopie-osm.png\" alt=\"Otoscopie d'une otite séromuqueuse : tympan rétracté, ambré, épanchement rétrotympanique\" loading=\"lazy\">\n        <figcaption>Otite séromuqueuse : tympan rétracté, d'aspect ambré, avec épanchement rétrotympanique (manche du marteau reconnaissable). Source : fiche source EDN item 150.</figcaption>\n      </figure>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 89 — Altération fonction auditive · 103 — <span class=\"kw-clinique\">Vertige</span> · 298 — Tumeur cavité buccale-nasosinusienne-cavum-VADS</em></p>","frequence":5},{"id":"150-9","rang":"A","rubrique":"Prise en charge","titre":"Connaître la stratégie initiale de prise en charge de l'otite externe et séro-muqueuse","contenu":"<p><strong><span class=\"kw-def\">Otite externe</span> :</strong></p>\n      <table >\n        <thead><tr><th style=\"width:38%\">Situation</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><th>Systématique</th><td><span class=\"kw-clinique\">Nettoyage</span> du conduit + traitement <span class=\"kw-ttt\">antalgique</span></td></tr>\n          <tr><th><span class=\"kw-etio\">Bactérienne</span> non compliquée</th><td><strong><span class=\"kw-ttt\">ATB locale</span> par gouttes de <span class=\"kw-ttt\">fluoroquinolones</span></strong> (<span class=\"kw-ttt\">ofloxacine</span>, <span class=\"kw-ttt\">ciprofloxacine</span>) pendant <span class=\"kw-chiffre\">5-7 jours</span> ; <span class=\"kw-clinique\">méchage</span> qui calibre le conduit pour faciliter l'instillation</td></tr>\n          <tr><th>Compliquée (<span class=\"kw-alerte\">périchondrite / chondrite</span>)</th><td><span class=\"kw-ttt\">ATB générale</span></td></tr>\n          <tr><th>Mycotique</th><td>Traitement local <span class=\"kw-ttt\">antimycotique</span></td></tr>\n        </tbody>\n      </table>\n\n      <p style=\"margin-top:14px\"><strong><span class=\"kw-def\">Otite séromuqueuse</span> (OSM) :</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Évolution</span> le plus souvent <strong>favorable / guérison spontanée</strong> → <span class=\"kw-chiffre\">surveillance</span> (contrôle à <span class=\"kw-chiffre\">3 mois</span>) ; lavages nasaux, traitement des FR (<span class=\"kw-etio\">rhinite</span>, <span class=\"kw-etio\">hypertrophie adénoïdienne</span>).</li>\n        <li><strong>Pose d'<span class=\"kw-ttt\">aérateurs transtympaniques</span> (ATT / diabolos)</strong> si OSM <span class=\"kw-chiffre\">&gt; 3 mois</span> avec :\n          <ul>\n            <li><span class=\"kw-clinique\">surdité de transmission</span> invalidante <span class=\"kw-chiffre\">&gt; 25-30 dB</span> ; ou</li>\n            <li><span class=\"kw-ttt\">réduction</span> de la fréquence des OMA chez l'enfant <span class=\"kw-chiffre\">&lt; 3 ans</span> (&gt; <span class=\"kw-chiffre\">5-6 épisodes/hiver</span>) ; ou</li>\n            <li>prévention de l'<span class=\"kw-clinique\">évolution</span> vers un <span class=\"kw-alerte\">cholestéatome</span> (poche de rétraction).</li>\n          </ul>\n        </li>\n        <li><span class=\"kw-ttt\">Adénoïdectomie</span> : en <span class=\"kw-bio\">complément</span> de l'ATT chez l'enfant <span class=\"kw-chiffre\">&gt; 4 ans</span> (otites récidivantes, obstruction).</li>\n        <li><span class=\"kw-clinique\">Bilan orthophonique</span> : seulement <strong>après guérison</strong> de l'OSM, si suspicion de retard de langage/parole/lecture.</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> <span class=\"kw-ci\">Pas d'antibiothérapie générale</span> dans l'OSM (ni dans l'otite congestive).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 89 — Altération fonction auditive</em></p>","frequence":2}],"astuces":[],"strategie":{"urgence":"<p><strong>OMA non compliquée :</strong> pas une <span class=\"kw-alerte\">urgence</span>, <span class=\"kw-ttt\">prise en charge ambulatoire</span><br><strong>Urgences ORL :</strong> <span class=\"kw-alerte\">mastoïdite</span>, <span class=\"kw-alerte\">paralysie faciale</span>, <span class=\"kw-alerte\">méningite</span> et <span class=\"kw-alerte\">otite maligne externe (nécrosante)</span> imposent une PEC immédiate<br><strong>Délai de <span class=\"kw-def\">réévaluation</span> :</strong> à <span class=\"kw-chiffre\">48-72h</span> si abstention d'antibiotique ou persistance des symptômes<br><strong>Geste urgent :</strong> <span class=\"kw-alerte\">pile bouton</span> dans le conduit = <span class=\"kw-ttt\">extraction en urgence</span> (risque de corrosion chimique)</p>","hospit":"<p><strong>Ambulatoire :</strong> la grande majorité des OMA<br><strong><span class=\"kw-alerte\">Hospitalisation</span> :</strong> réservée aux <span class=\"kw-alerte\">formes compliquées</span> (mastoïdite, <span class=\"kw-alerte\">méningite</span>, <span class=\"kw-clinique\">paralysie faciale</span>)<br><strong>Nourrisson < 3 mois :</strong> <span class=\"kw-ttt\">avis spécialisé en service hospitalier de pédiatrie générale</span><br><strong>Avis ORL :</strong> complications locorégionales, <span class=\"kw-etio\">OSM compliquée</span> (retentissement auditif, <span class=\"kw-etio\">cholestéatome</span>) ou <span class=\"kw-chiffre\">2e échec</span> antibiotique (<span class=\"kw-ttt\">paracentèse</span> bactériologique)</p>","redflags":"<ul><li><span class=\"kw-alerte\">Mastoïdite</span> : <span class=\"kw-clinique\">tuméfaction inflammatoire rétroauriculaire</span> avec <span class=\"kw-clinique\">décollement du pavillon</span> + syndrome général important</li><li><span class=\"kw-alerte\">Paralysie faciale périphérique</span> compliquant l'OMA</li><li><span class=\"kw-alerte\">Méningite</span> : <span class=\"kw-clinique\">syndrome méningé</span> et <span class=\"kw-clinique\">altération de l'état général</span></li><li><span class=\"kw-alerte\">Otite maligne externe (nécrosante)</span> : <span class=\"kw-def\">terrain</span> <span class=\"kw-etio\">diabétique</span>/<span class=\"kw-etio\">immunodéprimé</span>, otite externe traînante résistante au traitement local, <span class=\"kw-clinique\">paralysie de nerfs crâniens</span>, <span class=\"kw-radio\">polype du conduit auditif externe</span> (<span class=\"kw-etio\">Pseudomonas aeruginosa</span>)</li><li><span class=\"kw-clinique\">OSM unilatérale</span> → rechercher une <span class=\"kw-etio\">tumeur maligne du cavum</span> par nasofibroscopie</li><li><span class=\"kw-clinique\">Otorrhée chronique, fétide, récidivante</span> + <span class=\"kw-radio\">perforation marginale</span> à épidermose des berges → suspicion de <span class=\"kw-etio\">cholestéatome</span></li></ul>","principes":"<p>La conduite dépend de l'<span class=\"kw-clinique\">aspect otoscopique</span> (congestif <span class=\"kw-bio\">vs</span> purulent collecté), de l'<span class=\"kw-chiffre\">âge</span> et de l'<span class=\"kw-clinique\">intensité des symptômes</span> ; l'<span class=\"kw-ttt\">amoxicilline</span> reste l'antibiotique de 1re intention.</p><p><strong>Traitement symptomatique (systématique)</strong></p><p><span class=\"kw-ci\">Corticoïdes</span> et <span class=\"kw-ci\">vasoconstricteurs</span> non indiqués (prudence chez le nourrisson)</p><ul><li><span class=\"kw-ttt\">Désobstruction rhinopharyngée</span> au <span class=\"kw-ttt\">sérum physiologique</span> + mouchage</li><li><span class=\"kw-ttt\">Instillations auriculaires</span> à visée <span class=\"kw-ttt\">antalgique</span> et décongestionnante</li><li><span class=\"kw-ttt\">Paracétamol</span> et <span class=\"kw-ttt\">antalgiques</span> par voie générale ; <span class=\"kw-ttt\">ibuprofène</span> si <span class=\"kw-clinique\">douleur intense</span></li></ul><p><strong><span class=\"kw-ttt\">Antibiothérapie</span> générale : quand la prescrire ?</strong></p><p>Pas d'antibiotique dans l'<span class=\"kw-etio\">OMA congestive</span>, l'<span class=\"kw-etio\">otite séromuqueuse</span>, ni l'OMA purulente <span class=\"kw-chiffre\">≥ 2 ans</span> peu bruyante (abstention + <span class=\"kw-def\">surveillance</span>)</p><ul><li>OMA purulente de l'enfant <span class=\"kw-chiffre\">< 2 ans</span> : <span class=\"kw-ttt\">antibiothérapie systématique</span></li><li>OMA purulente <span class=\"kw-chiffre\">≥ 2 ans</span> : seulement si <span class=\"kw-clinique\">symptomatologie bruyante</span> (<span class=\"kw-clinique\">otalgie intense</span>, <span class=\"kw-clinique\">fièvre élevée</span>, <span class=\"kw-clinique\">otorrhée</span>)</li><li>OMA compliquant une maladie générale : <span class=\"kw-etio\">rougeole</span>, <span class=\"kw-etio\">varicelle</span>, <span class=\"kw-etio\">scarlatine</span></li><li>Otorrhée sur OMA perforée persistant <span class=\"kw-chiffre\">> 1 semaine</span> sans amélioration</li></ul><p><strong>Choix de l'antibiotique (probabiliste)</strong></p><p>Durée : <span class=\"kw-chiffre\">8-10 jours</span> si < 2 ans · <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">5 jours</span></span> si <span class=\"kw-chiffre\">≥ 2 ans</span> · <span class=\"kw-chiffre\">10 jours</span> si otorrhée ou rechute</p><ul><li>1re intention : <span class=\"kw-ttt\">amoxicilline</span> <span class=\"kw-chiffre\">80-90 mg/kg/j</span> en <span class=\"kw-chiffre\">3 prises</span></li><li><span class=\"kw-clinique\">Syndrome otite-conjonctivite</span> (<span class=\"kw-etio\">H. influenzae</span>) : <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span></li><li><span class=\"kw-ci\">Allergie</span> aux pénicillines (sans CI aux céphalosporines) : <span class=\"kw-ttt\">cefpodoxime-proxétil</span></li><li><span class=\"kw-ci\">Contre-indication à toutes les β-lactamines</span> : <span class=\"kw-ttt\">cotrimoxazole</span> ou <span class=\"kw-ttt\">érythromycine</span>-sulfafurazole</li><li>Voie parentérale (<span class=\"kw-chiffre\">< 3 mois</span>, immunodépression, intolérance digestive) : <span class=\"kw-ttt\">ceftriaxone IV/IM</span></li></ul><p><strong>Otite externe</strong></p><p><span class=\"kw-ci\">Aminosides locaux contre-indiqués</span> si perforation tympanique suspectée ou confirmée (ototoxicité)</p><ul><li><span class=\"kw-ttt\">Nettoyage</span> du conduit + <span class=\"kw-ttt\">antalgiques</span> systématiques</li><li><span class=\"kw-ttt\">Gouttes auriculaires de fluoroquinolone</span> (ofloxacine, <span class=\"kw-ttt\">ciprofloxacine</span>) <span class=\"kw-chiffre\">5-7 jours</span> ± <span class=\"kw-ttt\">méchage</span> du conduit œdématié</li><li>Si <span class=\"kw-etio\">origine mycotique</span> (<span class=\"kw-etio\">Aspergillus</span>) : <span class=\"kw-ttt\">antimycotique local</span></li><li><span class=\"kw-ttt\">Antibiothérapie générale</span> réservée aux formes graves étendues aux cartilages (<span class=\"kw-alerte\">périchondrite</span>, <span class=\"kw-alerte\">chondrite</span>)</li></ul><p><strong>Otite séromuqueuse (OSM)</strong></p><ul><li><span class=\"kw-ttt\">Pas d'antibiothérapie</span> ; surveillance, régression spontanée possible en <span class=\"kw-chiffre\">3 mois</span></li><li><span class=\"kw-ttt\">Aérateurs transtympaniques (ATT, diabolos)</span> si OSM évoluant depuis <span class=\"kw-chiffre\">> 3 mois</span> avec <span class=\"kw-clinique\">surdité de transmission</span> <span class=\"kw-chiffre\">> 25-30 dB</span></li><li>ATT aussi si <span class=\"kw-chiffre\">≥ 5-6 OMA</span> par hiver ou pour <span class=\"kw-ttt\">prévenir l'évolution vers un cholestéatome</span></li><li>± <span class=\"kw-ttt\">adénoïdectomie</span> (enfant <span class=\"kw-chiffre\">> 4 ans</span>) ; bilan orthophonique seulement après guérison de l'OSM</li></ul>","suivi":"<p><strong><span class=\"kw-def\">Réévaluation</span> :</strong> à <span class=\"kw-chiffre\">48-72h</span> en cas d'abstention d'antibiotique ou de persistance sous traitement<br><strong><span class=\"kw-clinique\">Évolution</span> favorable :</strong> amélioration des symptômes en <span class=\"kw-chiffre\">48-72h</span> ; si tympan perforé, fermeture vers <span class=\"kw-chiffre\">J3-J4</span><br><strong>Contrôle à distance :</strong> revoir à <span class=\"kw-chiffre\">4-6 semaines</span> pour dépister une <span class=\"kw-etio\">otite séromuqueuse</span> (complique <span class=\"kw-chiffre\">10-20%</span> des OMA)<br><strong>Échec (<span class=\"kw-chiffre\">5%</span> des cas) :</strong> persistance/aggravation après <span class=\"kw-chiffre\">48h</span> → relais par <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> ou <span class=\"kw-ttt\">cefpodoxime-proxétil</span> ; au <span class=\"kw-chiffre\">2e échec</span> → <span class=\"kw-ttt\">paracentèse</span> bactériologique<br><strong>OMA récidivantes :</strong> bilan immunitaire (<span class=\"kw-chiffre\">≥ 8/an</span> avant <span class=\"kw-chiffre\">4 ans</span>, <span class=\"kw-chiffre\">≥ 4/an</span> après, <span class=\"kw-chiffre\">≥ 2/an</span> chez l'adulte), <span class=\"kw-def\">dépistage</span> d'une <span class=\"kw-bio\">carence martiale</span>, avis ORL (<span class=\"kw-ttt\">adénoïdectomie</span>, <span class=\"kw-ttt\">aérateurs transtympaniques</span>)</p>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-150.pdf","label":"Pilly étudiant 2023 — item 150 (otites)"},{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/infectiologie/otites","label":"pedia-univ.fr — otites (référentiel pédiatrie)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"OMA suspectée : signe de complication ? — Mastoïdite, paralysie faciale, méningite, altération sévère de l'état général","detail":"<h4>CAT — Otite moyenne aiguë (OMA) de l'enfant — <span class=\"kw-ttt\">Antibiothérapie</span> selon l'aspect otoscopique, l'âge et l'intensité des symptômes (Afssaps 2011)</h4>","branches":[{"to":"t-complication","label":"Oui","color":"red"},{"to":"q-aspect","label":"Non","color":"green"}]},{"id":"t-complication","kind":"terminal","label":"Hospitalisation en urgence","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Hospitalisation</span> en <span class=\"kw-alerte\">urgence</span> ORL</li><li><span class=\"kw-ttt\">Antibiothérapie parentérale</span> adaptée au germe ± <span class=\"kw-ttt\">drainage / chirurgie</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-ttt\">Paracentèse</span> + <span class=\"kw-ttt\">ponction</span> de la collection pour prélèvement bactériologique</li><li><span class=\"kw-imagerie\">TDM injectée</span> (± <span class=\"kw-imagerie\">IRM</span> si suspicion d'extension endocrânienne)</li></ul>"},{"id":"q-aspect","kind":"decision","label":"Aspect otoscopique du tympan ? — L'otoscopie fait le diagnostic","branches":[{"to":"t-congestive","label":"Congestif (rouge, sans épanchement)","color":"green"},{"to":"q-age","label":"Purulent / collecté (épanchement, bombement, otorrhée)","color":"amber"}]},{"id":"t-congestive","kind":"terminal","label":"Pas d'antibiotique — OMA congestive (tympan rouge, sans épanchement)","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Traitement symptomatique</span> : désobstruction rhinopharyngée, <span class=\"kw-ttt\">antalgiques</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Revoir l'enfant si <span class=\"kw-clinique\">persistance des symptômes</span> au-delà du <span class=\"kw-chiffre\">3e jour</span></li></ul>"},{"id":"q-age","kind":"decision","label":"Âge de l'enfant ?","branches":[{"to":"t-nourrisson","label":"< 3 mois","color":"red"},{"to":"t-atb-jeune","label":"3 mois – 2 ans","color":"amber"},{"to":"q-symptomes","label":"≥ 2 ans","color":"blue"}]},{"id":"t-nourrisson","kind":"terminal","label":"Avis hospitalier pédiatrique — OMA purulente du nourrisson < <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> mois</span>","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Avis spécialisé</span> en service hospitalier de <span class=\"kw-ttt\">pédiatrie générale</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-ttt\">Paracentèse</span> pour prélèvement bactériologique</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Ceftriaxone</span> si voie parentérale nécessaire</li></ul>"},{"id":"t-atb-jeune","kind":"terminal","label":"Antibiothérapie systématique — OMA purulente, 3 mois – 2 ans","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Amoxicilline</span> <span class=\"kw-chiffre\">80-90 mg/kg/j</span> en <span class=\"kw-chiffre\">3 prises</span></li><li><span class=\"kw-ttt\">Amoxicilline-acide clavulanique</span> si <span class=\"kw-clinique\">syndrome otite-conjonctivite</span></li></ul><h4>Delai</h4><ul><li>Durée <span class=\"kw-chiffre\">8-10 jours</span></li></ul>"},{"id":"q-symptomes","kind":"decision","label":"Symptomatologie bruyante ? — Otalgie intense, fièvre élevée, otorrhée","branches":[{"to":"t-atb-grand","label":"Oui (bruyante)","color":"amber"},{"to":"t-abstention","label":"Non (peu bruyante)","color":"green"}]},{"id":"t-atb-grand","kind":"terminal","label":"Antibiothérapie — OMA purulente ≥ 2 ans, symptômes bruyants","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Amoxicilline</span> en 1re intention</li></ul><h4>Delai</h4><ul><li>Durée <span class=\"kw-chiffre\">5 jours</span> (<span class=\"kw-chiffre\">10 jours</span> si otorrhée ou rechute)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-clinique\">Réévaluation</span> à <span class=\"kw-chiffre\">48-72h</span></li></ul>"},{"id":"t-abstention","kind":"terminal","label":"Abstention + traitement symptomatique — OMA purulente ≥ 2 ans, symptômes peu bruyants","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Abstention d'antibiotique</span> + <span class=\"kw-ttt\">traitement symptomatique</span> seul</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-clinique\">Réévaluation</span> à <span class=\"kw-chiffre\">48-72h</span> ; <span class=\"kw-ttt\">antibiothérapie</span> si <span class=\"kw-alerte\">aggravation</span> ou persistance</li></ul>"}]},"cards":[{"i":"040d9ec45f21","n":150,"o":"150-1","u":"Définition","t":"Connaître les définitions : otalgie, différents types d'otites","q":"Quelle est la définition générale d'une otite ?","a":"<p>Une otite est une <strong>inflammation aiguë ou chronique de l'oreille</strong>.</p>"},{"i":"05b80118d288","n":150,"o":"150-1","u":"Définition","t":"Connaître les définitions : otalgie, différents types d'otites","q":"Quelles sont les caractéristiques otoscopiques de l'otite moyenne aiguë (OMA) purulente ?","a":"<p>Les caractéristiques otoscopiques de l'OMA purulente sont :</p><ul><li><strong>Inflammation tympanique : oui</strong> (tympan rouge).</li><li><strong>Épanchement rétrotympanique : oui</strong> (opaque).</li><li><strong>Otorrhée : oui</strong> si perforation tympanique.</li></ul>"},{"i":"16dfde5e9495","n":150,"o":"150-1","u":"Définition","t":"Connaître les définitions : otalgie, différents types d'otites","q":"Qu'est-ce qu'une otite moyenne chronique (OMC) et comment se distinguent les OMC bénignes des OMC dangereuses ?","a":"<p>Une otite moyenne chronique est un <strong>processus inflammatoire de l'oreille moyenne évoluant depuis plus de 3 mois</strong>.</p><ul><li>Les <strong>OMC bénignes</strong> sont non cholestéatomateuses (sans accumulation de kératine). Elles incluent l'otite séromuqueuse, l'otite chronique à tympan ouvert et certaines séquelles (tympanosclérose, otite atélectasique).</li><li>Les <strong>OMC dangereuses</strong> sont cholestéatomateuses (avec accumulation de kératine). Elles ne guérissent pas spontanément et présentent des risques de complications graves (paralysie faciale, labyrinthite, complications endocrâniennes).</li></ul>"},{"i":"23bb8605a83e","n":150,"o":"150-1","u":"Définition","t":"Connaître les définitions : otalgie, différents types d'otites","q":"Quelles sont les caractéristiques otoscopiques de l'otite externe (OE) ?","a":"<p>Les caractéristiques otoscopiques de l'otite externe sont :</p><ul><li><strong>Inflammation tympanique : non</strong> (l'atteinte est celle du conduit auditif externe).</li><li><strong>Épanchement rétrotympanique : non</strong>.</li><li><strong>Otorrhée : oui</strong>, souvent abondante.</li></ul>"},{"i":"52c1827efc56","n":150,"o":"150-1","u":"Définition","t":"Connaître les définitions : otalgie, différents types d'otites","q":"Comment définir l'otorrhée en ORL ?","a":"<p>L'otorrhée est un <strong>écoulement</strong> (clair ou purulent) provenant du <strong>conduit auditif externe</strong>. Elle est un signe d'affection de l'oreille, le plus souvent d'origine infectieuse (comme une otite externe ou une otite moyenne perforée).</p>"},{"i":"7dcddcbbed0c","n":150,"o":"150-1","u":"Définition","t":"Connaître les définitions : otalgie, différents types d'otites","q":"Qu'est-ce que l'otodynie et en quoi se distingue-t-elle de l'otalgie ?","a":"<p>L'otodynie est une <strong>otalgie spécifiquement liée à une affection de l'oreille elle-même</strong> (oreille moyenne ou externe). Contrairement à l'otalgie, l'otodynie implique directement une pathologie auriculaire.</p>"},{"i":"9a7dc946f3a4","n":150,"o":"150-1","u":"Définition","t":"Connaître les définitions : otalgie, différents types d'otites","q":"Quelle est la définition de l'otalgie et quels sont ses diagnostics différentiels ?","a":"<p>L'otalgie est une <strong>douleur localisée à l'oreille</strong>. Elle n'est pas toujours liée à une affection de l'oreille. Les diagnostics différentiels incluent :</p><ul><li>Bouchon de cérumen.</li><li>Otalgie réflexe d'origine buccopharyngée (pharyngite, angine, poussée dentaire).</li></ul>"},{"i":"a9bbab7658cd","n":150,"o":"150-1","u":"Définition","t":"Connaître les définitions : otalgie, différents types d'otites","q":"Quelles sont les caractéristiques otoscopiques de l'otite séromuqueuse (OSM) ?","a":"<p>Les caractéristiques otoscopiques de l'otite séromuqueuse sont :</p><ul><li><strong>Inflammation tympanique : non</strong> (tympan souvent rétracté).</li><li><strong>Épanchement rétrotympanique : oui</strong> (liquide clair).</li><li><strong>Otorrhée : non</strong> (sauf en présence d'un aérateur transtympanique ou de drains).</li></ul>"},{"i":"0df5e4135256","n":150,"o":"150-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d'OMA (démarche diagnostique, examen clinique dont otoscopie)","q":"Quels sont les diagnostics différentiels de l'otalgie à considérer face à une suspicion d'otite moyenne aiguë (OMA) ?","a":"<p>Les diagnostics différentiels de l'otalgie, surtout si l'otoscopie est normale, incluent :</p><ul><li>L'<strong>otite externe</strong> ou le furoncle du conduit : la douleur est lancinante, non paroxystique, exacerbée par la mastication, la pression du tragus ou la mobilisation du pavillon.</li><li>Le <strong>zona auriculaire</strong> : caractérisé par une éruption dans la conque (zone de Ramsay-Hunt) associée à une paralysie faciale.</li><li>L'<strong>otalgie réflexe</strong> (pharyngée, dentaire, ou liée à l'articulation temporo-mandibulaire - ATM) : à évoquer si l'otoscopie est rigoureusement normale.</li></ul>"},{"i":"5ff7f7cfc619","n":150,"o":"150-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d'OMA (démarche diagnostique, examen clinique dont otoscopie)","q":"Comment est établi le diagnostic positif d'une otite moyenne aiguë (OMA) ?","a":"<p>Le diagnostic d'otite moyenne aiguë est <strong>clinique et otoscopique</strong>. Seul un examen otoscopique de bonne qualité permet de confirmer le diagnostic et de différencier les types d'otite.</p>"},{"i":"7dbd95b9ab00","n":150,"o":"150-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d'OMA (démarche diagnostique, examen clinique dont otoscopie)","q":"Quels sont les signes otoscopiques de l'otite moyenne aiguë (OMA) aux stades congestif et collecté ?","a":"<p>L'otoscopie permet de distinguer <strong>deux stades</strong> :</p><ul><li><strong>Stade congestif</strong> : le tympan présente une <strong>congestion tympanique</strong> (rougeur, hypervascularisation), sans épanchement, avec des reliefs du marteau conservés et sans bombement.</li><li><strong>Stade collecté</strong> :<ul><li>Si le tympan est fermé : il est <strong>rouge violacé</strong>, avec disparition du triangle lumineux, <strong>bombement</strong> et disparition des reliefs, ainsi qu'une opacité rétrotympanique.</li><li>Si le tympan est perforé : présence d'une <strong>perforation punctiforme</strong> avec un écoulement pulsatile mucopurulent.</li></ul></li></ul>"},{"i":"b5114b5705b4","n":150,"o":"150-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d'OMA (démarche diagnostique, examen clinique dont otoscopie)","q":"Quels sont les éléments du contexte clinique et les symptômes orientant vers une otite moyenne aiguë (OMA) ?","a":"<p>Le contexte évoque une OMA <strong>au cours ou au décours d'une rhinopharyngite</strong>, avec ou sans fièvre. Les symptômes comprennent :</p><ul><li>Une <strong>fièvre</strong>.</li><li>Une <strong>otalgie</strong> par paroxysmes (décrite comme des « coliques de l'oreille »), exprimée verbalement chez l'enfant de ≥ 3 ans ou par des équivalents (pleurs, insomnie, irritabilité).</li><li>Une <strong>hypoacousie de transmission</strong>.</li><li>Une <strong>otorrhée</strong>, qui peut être le premier signe si le tympan est perforé (l'otalgie est alors peu marquée).</li></ul><p>Un signe associé est le <strong>syndrome otite-conjonctivite</strong> (conjonctivite purulente), orientant vers <em>Haemophilus influenzae</em> non typable.</p>"},{"i":"1fe166cda473","n":150,"o":"150-6","u":"Prise en charge","t":"Connaître la stratégie initiale de la prise en charge de l'OMA : antibiothérapie, traitements associés","q":"Quels sont les traitements symptomatiques de l'OMA à mettre en place systématiquement ?","a":"<ul><li><strong>Désobstruction rhinopharyngée</strong> : sérum physiologique + mouchage.</li><li><strong>Antalgiques</strong> : paracétamol ou ibuprofène (si douleur intense).</li><li><strong>Instillations auriculaires antalgiques</strong>.</li></ul><p>Les corticoïdes sont non indiqués et les vasoconstricteurs contre-indiqués (prudence chez le nourrisson).</p>"},{"i":"34769cbdaa7c","n":150,"o":"150-6","u":"Prise en charge","t":"Connaître la stratégie initiale de la prise en charge de l'OMA : antibiothérapie, traitements associés","q":"Quelles sont les situations où l'antibiothérapie n'est PAS indiquée en cas d'OMA ?","a":"<ul><li>OMA congestive (stade catarrhal).</li><li>Otite séromuqueuse.</li><li>Otite externe (sauf compliquée).</li><li>OMA purulente ≥ <strong>2 ans</strong> peu symptomatique : dans ce cas, une <strong>abstention-surveillance</strong> avec réévaluation à 48-72 h est licite.</li></ul>"},{"i":"6c38fb379548","n":150,"o":"150-6","u":"Prise en charge","t":"Connaître la stratégie initiale de la prise en charge de l'OMA : antibiothérapie, traitements associés","q":"Comment la durée de l'antibiothérapie est-elle adaptée pour une OMA ?","a":"<ul><li>Pour les enfants de < <strong>2 ans</strong> : <strong>8-10 jours</strong>.</li><li>Pour les enfants de ≥ <strong>2 ans</strong> : <strong>5 jours</strong>.</li><li>En cas d'otorrhée ou de rechute d'OMA purulente : <strong>10 jours</strong>.</li></ul>"},{"i":"847f3c39fc3d","n":150,"o":"150-6","u":"Prise en charge","t":"Connaître la stratégie initiale de la prise en charge de l'OMA : antibiothérapie, traitements associés","q":"Quel antibiotique est le traitement de première intention recommandé pour une OMA purulente non compliquée, et à quelle posologie ?","a":"<p>L'antibiotique de première intention est l'<strong>amoxicilline</strong> à la posologie de <strong>80-90 mg/kg/j</strong> en <strong>3 prises</strong>.</p>"},{"i":"b3c8e752bae3","n":150,"o":"150-6","u":"Prise en charge","t":"Connaître la stratégie initiale de la prise en charge de l'OMA : antibiothérapie, traitements associés","q":"Dans quelles situations l'antibiothérapie est-elle indiquée en cas d'OMA purulente ?","a":"<ul><li>OMA purulente < <strong>2 ans</strong>, systématiquement.</li><li>OMA purulente ≥ <strong>2 ans</strong> avec une symptomatologie bruyante (otalgie intense, fièvre élevée, otorrhée par perforation spontanée).</li><li>Persistance des symptômes après <strong>48-72 h</strong> de traitement symptomatique.</li><li>OMA compliquant une maladie générale (rougeole, varicelle, scarlatine).</li><li>Otorrhée sur OMA perforée persistant > <strong>1 semaine</strong>.</li></ul>"},{"i":"dd8b22ae2c72","n":150,"o":"150-6","u":"Prise en charge","t":"Connaître la stratégie initiale de la prise en charge de l'OMA : antibiothérapie, traitements associés","q":"Quel est le mécanisme de résistance du pneumocoque aux bêta-lactamines et l'utilité de l'acide clavulanique dans ce contexte ?","a":"<p>La résistance du pneumocoque est due à une <strong>modification de la cible (PLP)</strong>, et non pas à la production de bêta-lactamases. Par conséquent, l'<strong>acide clavulanique est inutile</strong> contre le pneumocoque. Il n'est utile qu'contre <em>Haemophilus influenzae</em> et <em>Moraxella catarrhalis</em> qui produisent, eux, des bêta-lactamases.</p>"},{"i":"e10c8c9a7f5e","n":150,"o":"150-6","u":"Prise en charge","t":"Connaître la stratégie initiale de la prise en charge de l'OMA : antibiothérapie, traitements associés","q":"Comment doit être orientée la prise en charge initiale d'une OMA chez l'enfant ?","a":"<p>La prise en charge initiale de l'OMA est le plus souvent <strong>ambulatoire</strong>. L'<strong>hospitalisation</strong> est réservée aux formes compliquées. Un avis ORL est rare, sauf en cas de complications locorégionales, d'otite séromuqueuse compliquée ou de 2<sup>e</sup> échec d'antibiothérapie.</p>"},{"i":"0bb62249c67c","n":150,"o":"150-8","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic de l'otite externe et séro-muqueuse","q":"Citez les éléments à l'otoscopie qui sont en faveur d'une otite externe.","a":"<p>À l'otoscopie, le <strong>conduit auditif externe</strong> (CAE) est <strong>inflammatoire, œdématié et douloureux</strong>, recouvert de sécrétions purulentes. Le tympan est généralement non inflammatoire et peut être difficile à analyser.</p>"},{"i":"0d1141c76142","n":150,"o":"150-8","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic de l'otite externe et séro-muqueuse","q":"Quels sont les signes cliniques de l'otite séro-muqueuse (OSM) ?","a":"<p>L'otite séro-muqueuse se manifeste principalement par une <strong>hypoacousie</strong> (souvent le mode de révélation), des otalgies fugaces, une sensation d'oreille pleine et une autophonie. Il n'y a <strong>pas de fièvre</strong>.</p>"},{"i":"1bddc487b7e1","n":150,"o":"150-8","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic de l'otite externe et séro-muqueuse","q":"Dans quel contexte doit-on évoquer une otite maligne externe (nécrosante) ?","a":"<p>Une otite maligne externe doit être évoquée chez un patient <strong>diabétique</strong>, <strong>immunodéprimé</strong> ou âgé, présentant une <strong>otite externe traînante</strong> résistante au traitement local, associée à un <strong>état général altéré (AEG)</strong> et/ou des paralysies de nerfs crâniens. La présence d'un polype du CAE est également évocatrice.</p>"},{"i":"631e203b759f","n":150,"o":"150-8","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic de l'otite externe et séro-muqueuse","q":"Quel est le piège diagnostique majeur concernant l'otite séro-muqueuse (OSM) et que faut-il rechercher dans ce cas ?","a":"<p>Le piège majeur est une <strong>otite séro-muqueuse unilatérale</strong>. Dans ce cas, il est impératif de rechercher une <strong>tumeur maligne du cavum</strong> par <strong>nasofibroscopie</strong>, y compris chez l'enfant.</p>"},{"i":"7999645bf42d","n":150,"o":"150-8","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic de l'otite externe et séro-muqueuse","q":"Quels sont les signes cliniques caractéristiques de l'otite externe ?","a":"<p>L'otite externe se manifeste par une <strong>otalgie intense</strong>, lancinante, majorée par la palpation du tragus ou la traction du pavillon. Elle est souvent accompagnée d'une <strong>otorrhée purulente</strong>. Il n'y a pas de fièvre associée.</p>"},{"i":"85c2d8ee28e3","n":150,"o":"150-8","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic de l'otite externe et séro-muqueuse","q":"Décrivez les signes otoscopiques de l'otite séro-muqueuse (OSM).","a":"<p>À l'otoscopie, le <strong>tympan</strong> est <strong>rétracté</strong>, d'aspect <strong>ambré, mat ou jaunâtre</strong>, avec parfois de fines stries vasculaires. Il est <strong>immobile</strong> au spéculum pneumatique de Siegle ou à la manœuvre de Valsalva. Un <strong>épanchement rétrotympanique</strong> (bulles, niveau liquidien) est souvent visible.</p>"},{"i":"de260b03704a","n":150,"o":"150-8","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic de l'otite externe et séro-muqueuse","q":"Quels examens paracliniques confirment le diagnostic d'otite séro-muqueuse (OSM) ?","a":"<ul><li>Une <strong>audiométrie</strong> montrera une <strong>surdité de transmission</strong>, avec une perte moyenne d'environ <strong>27 dB</strong>.</li><li>Un <strong>tympanogramme</strong> présentera une <strong>courbe plate de type B</strong>, témoignant de l'absence de mobilité tympanique.</li></ul>"},{"i":"1a00b1859d3a","n":150,"o":"150-9","u":"Prise en charge","t":"Connaître la stratégie initiale de prise en charge de l'otite externe et séro-muqueuse","q":"Quelle est la prise en charge initiale de l'otite séro-muqueuse (OSM) ?","a":"<p>L'otite séro-muqueuse (OSM) évolue le plus souvent vers une guérison spontanée. La prise en charge initiale repose sur :</p><ul><li>Une <strong>surveillance</strong>, avec un contrôle à <strong>3 mois</strong>.</li><li>Des <strong>lavages nasaux</strong>.</li><li>Le traitement des <strong>facteurs de risque</strong> (rhinite, hypertrophie adénoïdienne).</li><li>Il ne faut <strong>pas d'antibiothérapie générale</strong> dans l'OSM.</li></ul>"},{"i":"4f8ec7268b8a","n":150,"o":"150-9","u":"Prise en charge","t":"Connaître la stratégie initiale de prise en charge de l'otite externe et séro-muqueuse","q":"Dans quels cas la pose d'aérateurs transtympaniques (ATT) est-elle indiquée pour une otite séro-muqueuse (OSM) ?","a":"<p>La pose d'aérateurs transtympaniques (ATT ou diabolos) est indiquée si l'OSM persiste <strong>plus de 3 mois</strong> et s'associe à :</p><ul><li>Une <strong>surdité de transmission invalidante > 25-30 dB</strong>.</li><li>Une <strong>réduction de la fréquence des otites moyennes aiguës</strong> (OMA) chez l'enfant de moins de 3 ans (plus de <strong>5 à 6 épisodes par hiver</strong>).</li><li>Une <strong>prévention de l'évolution vers un cholestéatome</strong> (poche de rétraction).</li></ul>"},{"i":"8ea4071cf545","n":150,"o":"150-9","u":"Prise en charge","t":"Connaître la stratégie initiale de prise en charge de l'otite externe et séro-muqueuse","q":"Quand une adénoïdectomie est-elle envisagée en cas d'otite séro-muqueuse (OSM) ?","a":"<p>Une <strong>adénoïdectomie</strong> peut être envisagée <strong>en complément de la pose d'ATT</strong> chez l'enfant de <strong>plus de 4 ans</strong> présentant des otites récidivantes ou une obstruction.</p>"},{"i":"af7b977cafaf","n":150,"o":"150-9","u":"Prise en charge","t":"Connaître la stratégie initiale de prise en charge de l'otite externe et séro-muqueuse","q":"Quelle est la prise en charge initiale systématique de l'otite externe bactérienne non compliquée ?","a":"<p>La prise en charge initiale de l'otite externe bactérienne non compliquée repose sur :</p><ul><li>Un <strong>nettoyage du conduit auditif externe</strong>.</li><li>Un <strong>traitement antalgique</strong>.</li><li>Des <strong>antibiotiques locaux</strong> par gouttes de <strong>fluoroquinolones</strong> (ofloxacine, ciprofloxacine) pendant <strong>5 à 7 jours</strong>.</li><li>Un <strong>méchage</strong> du conduit pour faciliter l'instillation des gouttes.</li></ul>"},{"i":"e20ba6b89278","n":150,"o":"150-9","u":"Prise en charge","t":"Connaître la stratégie initiale de prise en charge de l'otite externe et séro-muqueuse","q":"Comment traiter une otite externe mycotique ou compliquée ?","a":"<ul><li>En cas d'<strong>otite externe mycotique</strong>, le traitement est un <strong>antimycotique local</strong>.</li><li>En cas d'<strong>otite externe compliquée</strong> (périchondrite/chondrite), un <strong>traitement antibiotique général</strong> est nécessaire.</li></ul>"}]};